import re
import os
from pathlib import Path
import glob


def task_func(directory_path: str, regex_pattern: str = r'\\(.+?\\)|\\w') -> dict:
    """
    Extract matches from all text files in a directory.

    Special behavior:
    - Text inside balanced parentheses is returned as one match, without the parentheses.
    - Any character outside parentheses is returned as an individual match.
    - For other regex patterns, standard regex finditer behavior is used.

    Returns:
        dict: {filename_without_path: [matches...]}
    """
    directory = Path(directory_path)

    if not directory.exists() or not directory.is_dir():
        return {}

    def _special_extract(text: str) -> list:
        pattern = re.compile(r"\((.*?)\)|[\s\S]", re.DOTALL)
        matches = []
        for match in pattern.finditer(text):
            inner = match.group(1)
            matches.append(inner if inner is not None else match.group(0))
        return matches

    def _generic_extract(text: str, pattern_text: str) -> list:
        compiled = re.compile(pattern_text)
        matches = []
        for match in compiled.finditer(text):
            groups = match.groups()
            if groups:
                selected = next((g for g in groups if g is not None), match.group(0))
                matches.append(selected)
            else:
                matches.append(match.group(0))
        return matches

    normalized_pattern = regex_pattern.replace("\\\\", "\\")

    results = {}
    file_paths = sorted(glob.glob(os.path.join(str(directory), "*")))

    for file_path in file_paths:
        if not os.path.isfile(file_path):
            continue

        file_name = Path(file_path).name

        try:
            with open(file_path, "r", encoding="utf-8", errors="ignore") as file:
                content = file.read()
        except OSError:
            results[file_name] = []
            continue

        if regex_pattern == r'\\(.+?\\)|\\w' or normalized_pattern == r'\(.+?\)|\w':
            matches = _special_extract(content)
        else:
            matches = _generic_extract(content, regex_pattern)

        results[file_name] = matches

    return results

import urllib.request
import zipfile
import os
import urllib.error

def task_func(
    url: str,
    save_path: str = "downloaded_file.zip",
    extract_path: str = "extracted_files",
) -> str:
    """
    Download a ZIP file from `url`, extract it into `extract_path`,
    delete the downloaded ZIP, and return the extraction directory path.

    Returns a descriptive error string on failure.
    """

    def _cleanup_downloaded_file() -> None:
        try:
            if os.path.exists(save_path):
                os.remove(save_path)
        except OSError:
            pass

    if not isinstance(url, str) or not url.strip():
        return "URL Error: Invalid URL"

    try:
        save_dir = os.path.dirname(os.path.abspath(save_path))
        if save_dir:
            os.makedirs(save_dir, exist_ok=True)

        extract_dir = os.path.abspath(extract_path)
        os.makedirs(extract_dir, exist_ok=True)
    except OSError as exc:
        return f"File Error: {exc}"

    try:
        with urllib.request.urlopen(url) as response, open(save_path, "wb") as out_file:
            while True:
                chunk = response.read(8192)
                if not chunk:
                    break
                out_file.write(chunk)
    except urllib.error.URLError as exc:
        _cleanup_downloaded_file()
        reason = getattr(exc, "reason", None)
        return f"URL Error: {reason if reason is not None else exc}"
    except ValueError as exc:
        _cleanup_downloaded_file()
        return f"URL Error: {exc}"
    except OSError as exc:
        _cleanup_downloaded_file()
        return f"File Error: {exc}"

    try:
        with zipfile.ZipFile(save_path, "r") as zf:
            for member in zf.infolist():
                target_path = os.path.abspath(os.path.join(extract_dir, member.filename))
                try:
                    common = os.path.commonpath([extract_dir, target_path])
                except ValueError as exc:
                    raise zipfile.BadZipFile(
                        f"Unsafe path in ZIP file: {member.filename}"
                    ) from exc

                if common != extract_dir:
                    raise zipfile.BadZipFile(
                        f"Unsafe path in ZIP file: {member.filename}"
                    )

            zf.extractall(extract_dir)
    except (zipfile.BadZipFile, zipfile.LargeZipFile, RuntimeError) as exc:
        _cleanup_downloaded_file()
        return f"ZIP Error: {exc}"
    except OSError as exc:
        _cleanup_downloaded_file()
        return f"File Error: {exc}"

    cleanup_error = None
    try:
        _cleanup_downloaded_file()
    except OSError as exc:
        cleanup_error = exc

    if cleanup_error is not None:
        return f"File Error: {cleanup_error}"

    return extract_dir

import pandas as pd
import json
import os
import shutil

def task_func(path):
    """
    Process JSON files in `path`, combine them into a single DataFrame,
    add a Source column with the filename, and move processed files to
    `path/processed`.

    Parameters
    ----------
    path : str or os.PathLike
        Directory containing JSON files.

    Returns
    -------
    pandas.DataFrame
        DataFrame containing the data from all processed files.
    """
    path = os.fspath(path)
    os.makedirs(path, exist_ok=True)

    processed_dir = os.path.join(path, "processed")
    os.makedirs(processed_dir, exist_ok=True)

    json_files = sorted(
        filename
        for filename in os.listdir(path)
        if filename.lower().endswith(".json")
        and os.path.isfile(os.path.join(path, filename))
    )

    frames = []

    for filename in json_files:
        file_path = os.path.join(path, filename)

        with open(file_path, "r", encoding="utf-8") as f:
            try:
                data = json.load(f)
            except json.JSONDecodeError:
                f.seek(0)
                data = pd.read_json(f)

        if isinstance(data, dict):
            df = pd.json_normalize(data)
        elif isinstance(data, list):
            if data and all(isinstance(item, dict) for item in data):
                df = pd.json_normalize(data)
            else:
                df = pd.DataFrame(data)
        else:
            df = pd.DataFrame([data])

        if "Source" in df.columns:
            df = df.drop(columns=["Source"])
        df.insert(0, "Source", filename)

        frames.append(df)

        destination = os.path.join(processed_dir, filename)
        if os.path.exists(destination):
            if os.path.isdir(destination):
                shutil.rmtree(destination)
            else:
                os.remove(destination)
        shutil.move(file_path, destination)

    if frames:
        return pd.concat(frames, ignore_index=True, sort=False)

    return pd.DataFrame()

