from openpyxl import load_workbook

def task_func(directory_path='./xlsx_files/'):
    """
    Prefix every double quote in string cells of each .xlsx workbook in the
    specified directory with two backslashes.

    Returns:
        int: The number of Excel files processed successfully.
    """
    if not os.path.isdir(directory_path):
        return 0

    quote_pattern = re.compile(r'"')
    replacement = '\\\\' + '"'

    xlsx_files = sorted(
        set(
            glob.glob(os.path.join(directory_path, '*.xlsx'))
            + glob.glob(os.path.join(directory_path, '*.XLSX'))
        )
    )

    processed = 0

    for file_path in xlsx_files:
        if os.path.basename(file_path).startswith('~$'):
            continue

        try:
            workbook = load_workbook(file_path)
        except Exception:
            continue

        try:
            for worksheet in workbook.worksheets:
                for row in worksheet.iter_rows():
                    for cell in row:
                        value = cell.value
                        if cell.data_type == 'f':
                            continue
                        if isinstance(value, str) and '"' in value:
                            cell.value = quote_pattern.sub(lambda _: replacement, value)

            workbook.save(file_path)
            processed += 1
        except Exception:
            # Skip files that cannot be updated safely.
            pass
        finally:
            try:
                workbook.close()
            except Exception:
                pass

    return processed

import os
from pathlib import Path
import pandas as pd
import docx


def _extract_text_from_txt_or_csv(file_path: Path) -> str:
    return file_path.read_text(encoding="utf-8", errors="replace")


def _extract_text_from_docx(file_path: Path) -> str:
    document = docx.Document(str(file_path))
    parts = []

    for paragraph in document.paragraphs:
        text = paragraph.text.strip()
        if text:
            parts.append(text)

    for table in document.tables:
        for row in table.rows:
            row_text = [cell.text.strip() for cell in row.cells if cell.text and cell.text.strip()]
            if row_text:
                parts.append(" | ".join(row_text))

    return "\n".join(parts)


def _extract_text_from_xlsx(file_path: Path) -> str:
    try:
        workbook = pd.read_excel(file_path, sheet_name=None, header=None, dtype=object)
    except ValueError:
        return ""

    parts = []
    for sheet_name, frame in workbook.items():
        sheet_parts = []
        for value in frame.to_numpy().ravel():
            if pd.notna(value):
                text = str(value).strip()
                if text:
                    sheet_parts.append(text)

        if sheet_parts:
            parts.append(f"[Sheet: {sheet_name}]")
            parts.extend(sheet_parts)

    return "\n".join(parts)


def _write_csv_with_single_text_column(text: str, output_path: Path) -> None:
    pd.DataFrame({"Text": [text]}).to_csv(output_path, index=False, encoding="utf-8")


def task_func(source_directory: str, target_directory: str) -> int:
    source_dir = Path(source_directory)
    target_dir = Path(target_directory)

    if not source_dir.exists() or not source_dir.is_dir():
        raise FileNotFoundError(f"Source directory does not exist: {source_directory}")

    os.makedirs(target_dir, exist_ok=True)

    converters = {
        ".txt": _extract_text_from_txt_or_csv,
        ".csv": _extract_text_from_txt_or_csv,
        ".docx": _extract_text_from_docx,
        ".xlsx": _extract_text_from_xlsx,
    }

    converted_count = 0

    for source_file in sorted(source_dir.iterdir()):
        if not source_file.is_file():
            continue

        converter = converters.get(source_file.suffix.lower())
        if converter is None:
            continue

        text_content = converter(source_file)
        output_file = target_dir / f"{source_file.stem}.csv"
        _write_csv_with_single_text_column(text_content, output_file)
        converted_count += 1

    return converted_count

import json
from datetime import datetime
from decimal import Decimal


def task_func(my_obj):
    def default_serializer(obj):
        if isinstance(obj, datetime):
            return obj.isoformat()
        if isinstance(obj, Decimal):
            if obj == obj.to_integral_value():
                return int(obj)
            return float(obj)
        if hasattr(obj, "__dict__"):
            return obj.__dict__
        return str(obj)

    return json.dumps(my_obj, default=default_serializer)

