def task_func(strings: list) -> dict:
    """
    Count how many times each string appears in the input list.

    Args:
        strings: A list of strings.

    Returns:
        A dictionary mapping each unique string to its occurrence count.
    """
    if strings is None:
        return {}

    return dict(Counter(strings))

import pandas as pd
import numpy as np
import matplotlib.pyplot as plt


def _convert_scalar_to_float(value):
    """Convert numeric-like scalar values to float while leaving others unchanged."""
    if pd.isna(value):
        return value
    if isinstance(value, (bool, np.bool_)):
        return float(value)
    if isinstance(value, (int, float, np.integer, np.floating)):
        return float(value)
    try:
        return float(str(value).strip())
    except (TypeError, ValueError):
        return value


def task_func(file_path="data.csv", columns=["A", "B", "C"]):
    df = pd.read_csv(file_path)

    # Convert numeric-like values to floats while keeping non-numeric values intact.
    converted_df = df.applymap(_convert_scalar_to_float)

    requested_columns = list(columns) if columns is not None else []

    # Support both column names and integer positions.
    selected_columns = []
    for col in requested_columns:
        if col in converted_df.columns:
            selected_columns.append(col)
        elif isinstance(col, int) and -len(converted_df.columns) <= col < len(converted_df.columns):
            selected_columns.append(converted_df.columns[col])

    # Fallback to all numeric columns if none of the requested columns exist.
    if not selected_columns:
        selected_columns = list(converted_df.select_dtypes(include=[np.number]).columns)

    fig, ax = plt.subplots()

    if selected_columns:
        plot_df = converted_df[selected_columns].apply(pd.to_numeric, errors="coerce").astype(float)
        plot_df.plot(ax=ax, kind="line")

        stacked = plot_df.stack(dropna=False)
        cube_root_series = pd.Series(
            np.cbrt(stacked.to_numpy(dtype=float)),
            index=stacked.index,
            name="cube_root",
        )
    else:
        cube_root_series = pd.Series(dtype=float, name="cube_root")

    ax.set_xlabel("Index")
    ax.set_ylabel("Value")
    ax.set_title("Line Chart")
    if selected_columns:
        ax.legend(title="Columns")

    fig.tight_layout()
    return converted_df, ax, cube_root_series

import struct
import zlib

# Constants
KEY = '470FC614'

def task_func(hex_string=KEY):
    """
    Convert a hexadecimal string representing a binary32 IEEE-754 value into
    a Python float, repack it as binary32, and return its zlib-compressed bytes.
    """
    if not isinstance(hex_string, str):
        raise TypeError("hex_string must be a string")

    cleaned = hex_string.strip().lower()
    if cleaned.startswith("0x"):
        cleaned = cleaned[2:]
    cleaned = "".join(cleaned.split())

    if not cleaned:
        raise ValueError("hex_string must not be empty")
    if len(cleaned) % 2 != 0:
        raise ValueError("hex_string must contain an even number of hex digits")

    try:
        raw = bytes.fromhex(cleaned)
    except ValueError as exc:
        raise ValueError("hex_string contains non-hex characters") from exc

    if len(raw) != 4:
        raise ValueError("hex_string must represent exactly 4 bytes for binary32")

    value = struct.unpack(">f", raw)[0]
    packed = struct.pack(">f", value)
    return zlib.compress(packed)
